Map<String, String> csrfTokens = new ConcurrentHashMap<>(); // sessionId -> csrfToken

server.createContext("/transfer", exchange -> {
    String sessionId = extractCookie(exchange, "SESSIONID");
    String providedToken = exchange.getRequestHeaders().getFirst("X-CSRF-Token");
    String expectedToken = csrfTokens.get(sessionId);
    if (expectedToken == null || !expectedToken.equals(providedToken)) {
        exchange.sendResponseHeaders(403, -1); // brak/zly token - odrzucone
        return;
    }
    processTransfer(exchange); // token poprawny - prawdziwe zadanie uzytkownika
});

